package com.dongqh.luckyhub.fulfillment.config;
import org.springframework.boot.context.properties.ConfigurationProperties;import java.time.Duration;
@ConfigurationProperties(prefix="luckyhub.fulfillment") public record FulfillmentProperties(Duration baseDelay,Duration maxDelay,Duration leaseDuration,Duration pollInterval,Duration initialDelay,int batchSize,int recoveryBatchSize){public FulfillmentProperties{positive(baseDelay,"baseDelay");positive(maxDelay,"maxDelay");positive(leaseDuration,"leaseDuration");positive(pollInterval,"pollInterval");if(initialDelay==null||initialDelay.isNegative())throw new IllegalArgumentException("initialDelay不能为负数");if(batchSize<1||batchSize>1000||recoveryBatchSize<1||recoveryBatchSize>1000)throw new IllegalArgumentException("batchSize必须为1到1000");if(maxDelay.compareTo(baseDelay)<0)throw new IllegalArgumentException("maxDelay不能小于baseDelay");}private static void positive(Duration v,String n){if(v==null||v.isZero()||v.isNegative())throw new IllegalArgumentException(n+"必须为正数");}}
